import React, { useState, useRef } from 'react';
import { FaFish, FaWater, FaTemperatureHigh, FaLeaf, FaInfo, FaRegStar, FaPlus } from 'react-icons/fa';
import { GiCoral, GiSeaweed, GiWaterDrop, GiUnderwater, GiVibratingBall } from 'react-icons/gi';
import { MdOutlineScience, MdCloudUpload } from 'react-icons/md';

function AquariumForm({ onAquariumCreate }) {
    const [name, setName] = useState('');
    const [photoUrl, setPhotoUrl] = useState('');
    const [photoFile, setPhotoFile] = useState(null);
    const [volume, setVolume] = useState('');
    const [type, setType] = useState('Planted');
    const [targetParameters, setTargetParameters] = useState(''); 
    const [initialSetupNotes, setInitialSetupNotes] = useState('');
    const [error, setError] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [submitSuccess, setSubmitSuccess] = useState(false);
    const fileInputRef = useRef(null);

    const handleDragOver = (e) => { e.preventDefault(); };
    const handleDrop = (e) => {
      e.preventDefault();
      const file = e.dataTransfer.files[0];
      if (file && file.type.startsWith('image/')) {
        setPhotoFile(file);
        const reader = new FileReader();
        reader.onload = (ev) => {
          setPhotoUrl(ev.target.result);
        };
        reader.readAsDataURL(file);
      } else {
        setError('Archivo no válido. Solo se permiten imágenes.');
      }
    };
    const handleFileSelect = (e) => {
      const file = e.target.files[0];
      if (file && file.type.startsWith('image/')) {
        setPhotoFile(file);
        const reader = new FileReader();
        reader.onload = (ev) => {
          setPhotoUrl(ev.target.result);
        };
        reader.readAsDataURL(file);
      } else {
        setError('Archivo no válido. Solo se permiten imágenes.');
      }
    };
    const handleAreaClick = () => {
      if (fileInputRef.current) fileInputRef.current.click();
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        if (!name || !volume) {
            setError('El nombre y el volumen son obligatorios.');
            return;
        }

        setIsSubmitting(true);
        setError('');

        // Simulamos una breve espera para mostrar la animación
        setTimeout(() => {
            const newAquarium = {
                id: Date.now().toString(), 
                name,
                photoUrl,
                volume: parseFloat(volume),
                type,
                targetParameters,
                initialSetupNotes
            };

            onAquariumCreate(newAquarium);

            // Mostrar animación de éxito
            setSubmitSuccess(true);

            // Resetear formulario después de un breve momento
            setTimeout(() => {
                setName('');
                setPhotoUrl('');
                setPhotoFile(null);
                setVolume('');
                setType('Planted');
                setTargetParameters('');
                setInitialSetupNotes('');
                setIsSubmitting(false);
                setSubmitSuccess(false);
            }, 800);
        }, 400);
    };

    return (
        <form onSubmit={handleSubmit} style={{ 
            marginBottom: '28px', 
            background: 'rgba(255,255,255,0.85)', 
            borderRadius: '18px', 
            boxShadow: '0 2px 12px 0 rgba(79,140,255,0.07)', 
            padding: '18px 16px',
            boxSizing: 'border-box',
            width: '100%',
            position: 'relative',
            overflow: 'hidden'
        }}>
            {submitSuccess && (
                <div style={{
                    position: 'absolute',
                    top: 0,
                    left: 0,
                    right: 0,
                    bottom: 0,
                    backgroundColor: 'rgba(52, 211, 153, 0.2)',
                    display: 'flex',
                    justifyContent: 'center',
                    alignItems: 'center',
                    zIndex: 10,
                    animation: 'fadeIn 0.3s ease-out'
                }}>
                    <div style={{
                        backgroundColor: 'rgba(52, 211, 153, 0.9)',
                        color: 'white',
                        padding: '12px 24px',
                        borderRadius: '12px',
                        fontWeight: '600',
                        animation: 'scaleIn 0.4s ease-out'
                    }}>
                        ¡Acuario añadido con éxito!
                    </div>
                </div>
            )}

            <h3 style={{textAlign: 'center', marginBottom: '16px'}}>Nuevo Acuario</h3>
            {error && <div style={{color:'#e11d48', marginBottom:'12px', fontWeight:500, fontSize:'1rem', animation: 'fadeIn 0.3s ease-out'}}>{error}</div>}
            <div className="form-group" style={{width:'100%', boxSizing:'border-box', marginBottom: '12px'}}>
                <label style={{display: 'block', marginBottom: '4px', display: 'flex', alignItems: 'center', gap: '4px'}}>
                    <FaFish /> Nombre
                </label>
                <input 
                    type="text" 
                    value={name} 
                    onChange={(e) => setName(e.target.value)} 
                    placeholder="Ej: Acuario principal" 
                    required 
                    style={{width: '100%', boxSizing: 'border-box', padding: '10px 12px', margin: '0'}}
                />
            </div>
            <div className="form-group" style={{width:'100%', boxSizing:'border-box', marginBottom: '12px'}}>
                <label style={{display: 'block', marginBottom: '4px', display: 'flex', alignItems: 'center', gap: '4px'}}>
                    <MdCloudUpload /> Foto del acuario
                </label>
                <div
                    onDragOver={handleDragOver}
                    onDrop={handleDrop}
                    onClick={handleAreaClick}
                    style={{
                        width: '100%',
                        height: '150px',
                        border: '2px dashed #ccc',
                        borderRadius: '12px',
                        display: 'flex',
                        justifyContent: 'center',
                        alignItems: 'center',
                        cursor: 'pointer',
                        marginBottom: '12px',
                        boxSizing: 'border-box',
                        overflow: 'hidden',
                        position: 'relative'
                    }}
                >
                    {photoUrl ? (
                        <img
                            src={photoUrl}
                            alt="Preview"
                            style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                        />
                    ) : (
                        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', color: '#888' }}>
                            <MdCloudUpload style={{ fontSize: '2rem', marginBottom: '8px' }} />
                            <span>Arrastra y suelta una imagen aquí o haz click para seleccionar</span>
                        </div>
                    )}
                    <input
                        type="file"
                        accept="image/*"
                        ref={fileInputRef}
                        onChange={handleFileSelect}
                        style={{ display: 'none' }}
                    />
                </div>
            </div>
            <div className="form-group" style={{width:'100%', boxSizing:'border-box', marginBottom: '12px'}}>
                <label style={{display: 'block', marginBottom: '4px', display: 'flex', alignItems: 'center', gap: '4px'}}>
                    <FaWater /> Volumen (litros)
                </label>
                <input 
                    type="number" 
                    value={volume} 
                    onChange={(e) => setVolume(e.target.value)} 
                    min="1" 
                    step="0.1" 
                    placeholder="Ej: 120" 
                    required 
                    style={{width: '100%', boxSizing: 'border-box', padding: '10px 12px', margin: '0'}}
                />
            </div>
            <div className="form-group" style={{width:'100%', boxSizing:'border-box', marginBottom: '12px'}}>
                <label style={{display: 'block', marginBottom: '4px', display: 'flex', alignItems: 'center', gap: '4px'}}>
                    <GiUnderwater /> Tipo
                </label>
                <select 
                    value={type} 
                    onChange={(e) => setType(e.target.value)}
                    style={{width: '100%', boxSizing: 'border-box', padding: '10px 12px', margin: '0'}}
                >
                    <option value="Planted">Plantado</option>
                    <option value="Community">Comunitario</option>
                    <option value="Marine">Marino (solo peces)</option>
                    <option value="Reef">Reef (marino con corales)</option>
                    <option value="Brackish">Agua salobre</option>
                    <option value="Coldwater">Agua fría</option>
                    <option value="Species-specific">Específico (ej: Betta, Gambas)</option>
                    <option value="Other">Otro</option>
                </select>
            </div>
            <div className="form-group" style={{width:'100%', boxSizing:'border-box', marginBottom: '12px'}}>
                <label style={{display: 'block', marginBottom: '4px', display: 'flex', alignItems: 'center', gap: '4px'}}>
                    <MdOutlineScience /> Parámetros objetivo
                </label>
                <input 
                    type="text" 
                    value={targetParameters} 
                    onChange={(e) => setTargetParameters(e.target.value)} 
                    placeholder="Ej: pH 7, Temp 25ºC" 
                    style={{width: '100%', boxSizing: 'border-box', padding: '10px 12px', margin: '0'}}
                />
            </div>
            <div className="form-group" style={{width:'100%', boxSizing:'border-box', marginBottom: '12px'}}>
                <label style={{display: 'block', marginBottom: '4px', display: 'flex', alignItems: 'center', gap: '4px'}}>
                    <FaInfo /> Notas de configuración inicial
                </label>
                <textarea 
                    value={initialSetupNotes} 
                    onChange={(e) => setInitialSetupNotes(e.target.value)} 
                    placeholder="Observaciones, equipamiento, etc."
                    style={{width: '100%', boxSizing: 'border-box', padding: '10px 12px', margin: '0', minHeight: '80px'}} 
                />
            </div>
            <button 
                type="submit" 
                style={{
                    width: '100%', 
                    marginTop: '8px',
                    position: 'relative',
                    overflow: 'hidden'
                }}
                disabled={isSubmitting}
            >
                {isSubmitting ? (
                    <span style={{display: 'inline-flex', alignItems: 'center', gap: '8px', animation: 'pulse 1s infinite'}}>
                        <span className="loading-spinner"></span> Añadiendo...
                    </span>
                ) : (
                    <span style={{display: 'inline-flex', alignItems: 'center', gap: '8px'}}>
                        <FaPlus /> Añadir acuario
                    </span>
                )}
            </button>
        </form>
    );
}

export default AquariumForm;
